<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';require __DIR__.'/../src/Web/View.php';
use Kulturhus\Verein\{Database,Registry,WebsiteCalendar,EventGema};
use Kulturhus\Verein\Tests\MySqlFixture;
set_error_handler(static function($s,$m,$f,$l){throw new ErrorException($m,0,$s,$f,$l);});
$n=0;
function check(bool $ok,string $label):void{global $n;if(!$ok)throw new RuntimeException($label);++$n;echo "PASS $label\n";}
function denied(callable $fn,string $label):void{try{$fn();}catch(DomainException){check(true,$label);return;}throw new RuntimeException($label);}
$db=MySqlFixture::connect(':memory:');Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','Synthetic A'),('b','Synthetic B'); INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','members',1),('other','b','members',1),('member','a','member',0)");
$websiteRow=['id'=>1,'external_id'=>'event-1','title'=>'Website-Abend','summary'=>'','venue_name'=>'Test','venue_address'=>'','path'=>'/veranstaltungen/test/','status'=>'live','start_at'=>strtotime('2026-07-01T18:00:00Z'),'end_at'=>strtotime('2026-07-01T20:00:00Z')];
$website=new WebsiteCalendar('a',static fn()=>['complete'=>true,'rows'=>[$websiteRow,$websiteRow]]);
$registry=new Registry($db,'admin',$website);$gema=new EventGema($db,'admin',$registry);
$create=static fn(Registry $r,string $title,string $date)=>$r->saveAppointment(null,0,['title'=>$title,'start'=>$date.'T18:00','end'=>$date.'T21:00','category'=>'verein'],[]);
$past=$create($registry,'Januar <Abend>','2026-01-02');$future=$create($registry,'Dezemberabend','2026-12-20');
$otherYear=$create($registry,'Anderes Jahr','2025-06-02');$moved=$create($registry,'Verschoben','2025-08-02');
$foreign=$create(new Registry($db,'other'),'Fremder Verein','2026-06-02');
$gema->checklist($past,0,'yes',true,'submitted');$gema->checklist($moved,0,'no',false,'not_required','Ursprüngliche Prüfung: Tätigkeit ohne Musiknutzung.');
$registry->saveAppointment($moved,1,['title'=>'Jetzt im Februar','start'=>'2026-02-02T18:00','end'=>'2026-02-02T21:00','category'=>'verein'],[]);
$midnight=$registry->saveAppointment(null,0,['title'=>'Jahresanfang','start'=>'2026-01-01T00:00','end'=>'2026-01-01T01:00','category'=>'verein'],[]);
$before=[];foreach(['event_gema','appointments','audit_events','finance_entries','club_outbox'] as $table)$before[$table]=MySqlFixture::rows($db,$table);
$rows=$gema->yearEvents(2026);$byId=array_column($rows,null,'event_id');
check(array_column($rows,'event_id')===[$midnight,$past,$moved,'website:1',$future],'all yearly events in time order, no music classification required');
check($byId[$midnight]['event_date']==='2026-01-01','year boundary follows local German date');
check($byId[$past]['status']==='registered'&&$byId[$past]['setlist']==='submitted','past registration and setlist retained');
check($byId[$future]['status']==='check','unclassified future event is visible without creating GEMA data');
check($byId[$moved]['status']==='not_required'&&$byId[$moved]['event_title']==='Jetzt im Februar','rescheduled event preserves status and uses current title');
check(!isset($byId[$foreign],$byId[$otherYear]),'other club and other year excluded');
check(count(array_filter($rows,fn($r)=>$r['event_id']==='website:1'))===1,'website duplicates appear once');
check(count((new EventGema($db,'other',new Registry($db,'other',$website)))->yearEvents(2026))===1,'website source cannot leak to another club');
denied(fn()=>(new EventGema($db,'member',new Registry($db,'member',$website)))->yearEvents(2026),'ordinary member cannot read board overview');
foreach([1999,2101] as $year)denied(fn()=>$gema->yearEvents($year),'invalid year '.$year.' rejected');
$_SESSION=['actor'=>'admin'];$_GET=['year'=>'2026'];$_POST=[];
ob_start();require __DIR__.'/../views/Events/gema-overview.php';$html=ob_get_clean();
check(str_contains($html,'Januar &lt;Abend&gt;')&&str_contains($html,'Dezemberabend')&&str_contains($html,'Website-Abend'),'yearly view contains past, future and website events, safely escaped');
check(!str_contains($html,'Weitere Kalendertermine prüfen')&&!str_contains($html,'als Musikveranstaltung markiert'),'no hidden second list or classification prerequisite');
check(substr_count($html,'<tbody>')===1&&substr_count($html,'<tr>')===6,'one complete table');
$_GET=['year'=>'2024'];ob_start();require __DIR__.'/../views/Events/gema-overview.php';$empty=ob_get_clean();
check(str_contains($empty,'keine Veranstaltungen vorhanden'),'empty year has plain empty state');
$registry=new Registry($db,'admin',new WebsiteCalendar('a',static fn()=>['complete'=>false,'rows'=>[]]));$_GET=['year'=>'2026'];
ob_start();require __DIR__.'/../views/Events/gema-overview.php';$incomplete=ob_get_clean();
check(str_contains($incomplete,'role="alert"')&&str_contains($incomplete,'möglicherweise unvollständig'),'failed website source is not silently presented as a complete year');
foreach($before as $table=>$data)check(MySqlFixture::rows($db,$table)===$data,'overview does not mutate '.$table);
echo "$n yearly GEMA checks passed\n";
